<script setup lang="ts">
import { uiText } from "../uiText";
import{computed,ref}from'vue';
import type{Match}from'../../bindings/leaguepingo/internal/core/models';
import{heroRows,recentSeven}from'../analysisData';
import{championName}from'../gameAssets';
import{decimal,percent}from'../presentation';
import GameIcon from'./GameIcon.vue';
const props=defineProps<{matches:Match[];fetchedAt?:string|null;scope:string}>();
const window=ref('sample'),query=ref(''),all=ref(false);
const rows=computed(()=>heroRows(window.value==='week'?recentSeven(props.matches,props.fetchedAt):props.matches).filter(h=>championName(h.id).toLowerCase().includes(query.value.toLowerCase())));
</script>
<template><section class="champion-analysis"><header><h2>{{ uiText.common.champions }}</h2><select v-model="window" :aria-label="uiText.championAnalysis.scope"><option value="sample">{{ uiText.championAnalysis.recentSample }}</option><option value="week">{{ uiText.championAnalysis.sevenDays }}</option></select></header><div class="champion-query"><input v-model="query" type="search" :aria-label="uiText.championAnalysis.searchLabel" :placeholder="uiText.common.searchPlaceholder"/><span>{{scope}}</span></div><div class="champion-table"><table><thead><tr><th>{{ uiText.common.champion }}</th><th>{{ uiText.championAnalysis.kdaCs }}</th><th>{{ uiText.common.winRateGames }}</th></tr></thead><tbody><tr v-for="hero in rows.slice(0,all?rows.length:5)" :key="hero.id"><td><div><GameIcon :id="hero.id" :size="34"/><strong :title="championName(hero.id)">{{championName(hero.id).split('·')[0]}}</strong></div></td><td><b>{{decimal(hero.kda)}}</b><small>{{ uiText.championAnalysis.csPerMinute(hero.csRate==null?'—':hero.csRate.toFixed(1)) }}</small></td><td><b>{{percent(hero.winRate)}}</b><span v-if="hero.outcomeGames" class="hero-outcomes" :title="uiText.championAnalysis.outcomeDetail(hero.wins, hero.losses, hero.outcomeGames)"><i :style="{width:`${hero.winRate??0}%`}"/></span><small>{{ uiText.common.games(hero.games) }}</small></td></tr><tr v-if="!rows.length"><td colspan="3" class="champion-empty">{{query?uiText.championAnalysis.noMatch:uiText.championAnalysis.empty}}</td></tr></tbody></table></div><button v-if="rows.length>5" class="champion-more" @click="all=!all">{{all?uiText.championAnalysis.collapse:uiText.common.expandChampions(rows.length)}}</button><p class="champion-scope">{{ uiText.championAnalysis.scopeHelp(window==='week'?uiText.championAnalysis.sevenDayScope:uiText.championAnalysis.currentScope) }}</p></section></template>
<style scoped>.champion-analysis{min-width:0;background:var(--panel);border:1px solid var(--border);border-radius:8px;overflow:hidden;}.champion-analysis>header{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:9px 12px;border-bottom:1px solid var(--border);min-height:40px;}.champion-analysis h2{font-size:13px;margin:0;white-space:nowrap;}.champion-analysis select{font-size:11px;max-width:130px;min-height:26px;padding:4px 20px 4px 6px;}.champion-query{padding:8px 10px;}.champion-query input{width:100%;font-size:12px;min-height:30px;}.champion-query>span{display:block;font-size:11px;color:var(--muted);margin-top:6px;}.champion-table table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums;}.champion-table th{text-align:right;font-size:11px;color:var(--muted);font-weight:400;padding:4px 10px 7px;white-space:nowrap;}.champion-table th:first-child{text-align:left;}.champion-table td{font-size:12px;text-align:right;padding:8px 10px;border-top:1px solid var(--border);}.champion-table td:first-child{width:44%;text-align:left;}.champion-table td:first-child>div{display:flex;align-items:center;gap:7px;}.champion-table td strong{font-size:13px;font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:90px;}.champion-table td b{font-size:13px;font-weight:500;}.champion-table td small{display:block;font-size:11px;color:var(--muted);margin-top:4px;white-space:nowrap;}.champion-table td.champion-empty{text-align:center;color:var(--muted);padding:22px 12px;}.champion-more{width:100%;border:0;border-top:1px solid var(--border);border-radius:0;background:none;color:var(--accent);padding:9px;font-size:12px;}.hero-outcomes{display:block;height:3px;background:var(--loss);margin-top:5px;width:50px;margin-left:auto;opacity:.8;}.hero-outcomes i{display:block;height:100%;background:var(--win);}.champion-scope{font-size:11px;color:var(--muted);line-height:1.6;padding:9px 12px;border-top:1px solid var(--border);margin:0;}</style>
